import java.util.Scanner;

public class Main {
    public static double absoluteValue(double num) {
        return num < 0 ? -num : num;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int n = sc.nextInt();

        int bestX = 0;
        int bestY = 0;
        double minDifference = 1e100;

        for (int i = 1; i <= n; i++) {
            int x = i;
            int yUpper = (int) ((double) a / b * i);
            int yLower = yUpper + 1;

            double diffUpper = absoluteValue((double) a / b - (double) yUpper / x);
            double diffLower = absoluteValue((double) a / b - (double) yLower / x);

            if (minDifference > diffUpper) {
                minDifference = diffUpper;
                bestX = yUpper;
                bestY = x;
            }
            if (minDifference > diffLower) {
                minDifference = diffLower;
                bestX = yLower;
                bestY = x;
            }
        }
        System.out.println(bestX + "/" + bestY);
        sc.close();
    }
}
